function getApi() {
  return globalThis.STBaiBaiBook ?? null;
}
function getBaiBaiSummary() {
  const api = getApi();
  if (!api) return null;
  try {
    const injected = api.getInjectedHistory();
    if (injected?.relativeText) return injected.relativeText;
    const chat = window.SillyTavern?.getContext?.()?.chat;
    const len = chat?.length ?? 0;
    if (len > 0) {
      const hist = api.getHistory({ before: len });
      if (hist?.relativeText) return hist.relativeText;
    }
  } catch (e) {
    console.warn("[Choice][BaiBaiBook] 获取摘要失败:", e);
  }
  return null;
}
function getBaiBaiState() {
  const api = getApi();
  if (!api) return null;
  try {
    const snap = api.getSnapshot();
    if (!snap) return null;
    const groups = [];
    const st = snap.state;
    if (st?.time || st?.location) {
      const loc = st.locationPath?.length ? st.locationPath.join(" > ") : st.location;
      const parts = [st.time ? `时间: ${st.time}` : "", loc ? `地点: ${loc}` : ""].filter(Boolean);
      if (parts.length) groups.push(`[当前状态]
${parts.join(" / ")}`);
    }
    const situationLines = [];
    if (snap.scenes?.length) {
      const sceneText = snap.scenes.map((s) => {
        const name = s.name || s.title || "";
        const desc = s.description || s.desc || "";
        return name && desc ? `${name}: ${desc}` : name || desc;
      }).filter(Boolean).join("；");
      if (sceneText) situationLines.push(`场景: ${sceneText}`);
    }
    if (snap.npcs?.length) {
      const npcText = snap.npcs.map((n) => {
        const name = n.name || "";
        const info = [n.identity, n.appearance, n.condition].filter(Boolean).join(" / ");
        return name && info ? `${name}(${info})` : name || info;
      }).filter(Boolean).join("；");
      if (npcText) situationLines.push(`NPC: ${npcText}`);
    }
    if (snap.vars && Object.keys(snap.vars).length > 0) {
      const varText = JSON.stringify(snap.vars);
      if (varText !== "{}") situationLines.push(`变量: ${varText}`);
    }
    if (situationLines.length) groups.push(`[当前互动局势]
${situationLines.join("\n")}`);
    const p = snap.protagonist;
    if (p) {
      const fields = [
        p.gender ? `性别: ${p.gender}` : "",
        p.identity ? `身份: ${p.identity}` : "",
        p.appearance ? `外貌: ${p.appearance}` : "",
        p.outfit ? `衣着: ${p.outfit}` : "",
        p.condition ? `状况: ${p.condition}` : ""
      ].filter(Boolean);
      if (fields.length) groups.push(`[主角当前状态]
${fields.join(" / ")}`);
    }
    return groups.length ? groups.join("\n\n") : null;
  } catch (e) {
    console.warn("[Choice][BaiBaiBook] 获取状态失败:", e);
  }
  return null;
}

const modules = [{"id":"system_prompt","name":"头部","role":"system","content":"你是一个专门为角色扮演对话生成\"行动选项\"或对用户输入进行\"润色扩展\"的辅助工具，独立运行于主对话生成流程之外。你的输出不会成为正文的一部分，仅供 {{user}} 在正文继续前作为行动参考或输入草稿。\n\n你有且只有两种工作模式：\n模式一·选项生成：根据当前场景状态（以 <current_scene> 标记的最新消息为准），为 {{user}} 提供若干条彼此独立、方向各异的可选行动方案。\n模式二·输入润色：将 {{user}} 的原始输入改写为若干个语义不变、表达更丰富的版本。\n\n每次任务只属于其中一种模式，具体任务将在下方用户指令中明确指定。无论哪种模式，你都必须严格遵守后续系统消息中给出的格式与内容规则，不得输出规则之外的任何文字、寒暄或说明。","marker":false,"system":false,"enabled":true,"order":0},{"id":"assistant_ack","name":"AI 应答","role":"assistant","content":"收到。我是独立于正文之外的选项生成/润色工具，本轮将先判断任务属于哪种模式，再严格按照系统规则执行，不输出任何多余内容。","marker":false,"system":false,"enabled":true,"order":1},{"id":"user_instruction","name":"生成指令","role":"user","content":"【任务：选项生成】请为角色当前处境生成恰好 {{count}} 条行动选项，不多不少。\n\n【固定条目】（共 {{pinned_count}} 条，本轮必须全部包含，不受下方条件过滤影响）：\n{{pinned}}\n\n【候选条目池】（每条可能带 [条件: xxx] 标记；仅当当前上下文明确满足该条件时才可选用，否则直接跳过，不得为凑数而强行关联）：\n{{pool_selected}}\n\n生成要求：\n1. {{count}} 条选项两两之间在切入点、行动类型、情绪态度上必须有清晰可辨的差异，禁止本质同质、只是换皮表述。\n2. 每条选项由\"标题\"与\"内容\"两部分组成，具体格式、字数、措辞禁忌见系统消息中的核心规则，此处不再重复。\n3. 候选条目的条件过滤是本轮唯一的取舍依据：条件满足才使用，条件不满足或无法判断则舍弃。\n4. 输出顺序固定为：先输出完整的 <thinking> 分析块，再输出 <options> 选项块，两者之外不得有任何文字。\n5. <options> 内每行一条选项，条数必须与 {{count}} 完全一致。","marker":false,"system":false,"enabled":true,"order":2,"option_only":true},{"id":"enrich_prompt","name":"润色提示词","role":"user","content":"【任务：输入润色】请将下方【用户输入】润色扩展为 {{count}} 个版本。保留原意和语气，通过增加细节描写使表达更生动自然。{{count}} 个版本之间在描写方式、措辞风格上应有明显差异，避免全部雷同。\n\n【用户输入】\n{{input}}\n\n【输出格式】\n先输出 <thinking> 自检分析，再输出 <options> 包裹的 {{count}} 个版本，每行格式为 \"[标题]内容\"。严禁在版本内容中使用[]符号。详细规则与规格见系统消息。","marker":false,"system":false,"enabled":true,"order":3,"enrich_only":true},{"id":"reference_open","name":"参考开始","role":"system","content":"<!-- 角色扮演参考资料 -->\n<reference>","marker":false,"system":false,"enabled":true,"order":4},{"id":"world_info_before","name":"World Info (before)","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":5},{"id":"persona_description","name":"Persona Description","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":6},{"id":"char_description","name":"Character Description","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":7},{"id":"char_personality","name":"Character Personality","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":8},{"id":"char_scenario","name":"Character Scenario","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":9},{"id":"world_info_after","name":"World Info (after)","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":10},{"id":"baibai_summary","name":"柏宝书摘要","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":13},{"id":"baibai_state","name":"柏宝书状态","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":16},{"id":"reference_close","name":"参考结束","role":"system","content":"</reference>","marker":false,"system":false,"enabled":true,"order":11},{"id":"history_open","name":"历史开始","role":"system","content":"<!-- 角色扮演交互历史 -->\n<history>","marker":false,"system":false,"enabled":true,"order":12},{"id":"chat_history","name":"Chat History","role":"system","content":"","marker":true,"system":true,"enabled":true,"order":14},{"id":"history_close","name":"历史结束","role":"system","content":"</history>","marker":false,"system":false,"enabled":true,"order":15},{"id":"core_rules","name":"规则","role":"system","content":"【核心规则 - 生成选项时严格遵守】\n\n1. 选项内容独立于正文之外，{{user}} 在选项中描述的行为视为\"尚未发生\"，只是待选的行动意图。\n2. 选项必须基于 <current_scene> 标签内的最新场景状态生成。\n3. 严禁在选项内替其他角色做出反应、决定或心理判断；不得与已离场/不存在的角色互动，不得凭空变出场景中未出现过的道具。\n4. 含言语交流的选项必须给出具体可朗读的对白，不得用概括动词一带而过。对白用『……』标注。\n5. 选项描述的行为必须是未完成状态，禁止使用裁定性词汇（成功/失败/导致/终于等），这类词汇会预先裁定其他角色的反应。\n6. {{count}} 条选项之间在切入点、行动类型、情绪态度上必须有清晰可辨的差异，禁止本质同质。\n7. 全部选项包裹在 <options> 标签内，每个选项独占一行，格式为\"[标题]内容\"。严禁在选项内容中使用[]符号。除 <thinking> 与 <options> 外不得输出任何文字。\n8. 每个选项字数控制在 {{min_chars}}-{{max_chars}} 个中文字符。\n\n【正误示例】\n错误：\"[『你为什么在这？』]{{user}}感到很疑惑。\"（对白当标题+越权裁定）\n错误：\"[追问]{{user}}问他：『为什么？』他听后低下了头。\"（对话引导冒号+越权代演）\n正确：\"[寻找铁罐]{{user}}向她微微点头，随后径直走向基座，蹲下身在积满灰尘的杂物中仔细翻找。\"\n正确：\"[强势打断]『够了。』{{user}}毫不留情地打断了她的话，指尖不耐烦地轻叩着桌面。\"","marker":false,"system":false,"enabled":true,"order":17,"option_only":true},{"id":"output_spec","name":"输出规格","role":"system","content":"【输出规格】\n\n数量：恰好 {{count}} 条，不多不少。\n\n格式：每条选项独占一行，格式为 \"[标题]内容\"\n- 标题：简洁概括选项的核心行动，用[]包裹\n- 正文：选项的具体内容，严禁使用[]符号\n\n输出结构：\n1. 先输出完整的 <thinking> 分析块\n2. 再输出 <options> 选项块，每个选项独占一行\n3. 两者之外不得有任何文字","marker":false,"system":false,"enabled":true,"order":18,"option_only":true},{"id":"thinking_prompt","name":"思考检查","role":"system","content":"【输出前自检 - 全部内容须包裹在 <thinking> 标签内】\n请按顺序逐条检查并简要记录结论：\n1. 场景核查：当前在场角色有哪些？谁已离开或不存在？\n2. 任务确认：本轮任务是【选项生成】还是【润色扩展】？数量要求 {{count}} 条？固定条目是否已全部纳入？候选条目的 [条件] 是否逐条核实？\n3. 差异化与违规词检查：各选项在切入点、行动类型、情绪态度上是否两两不同？是否出现越权代演、裁定性词汇、完成态表述？若有，逐一改写。\n4. 格式与字数检查：是否包裹在 <options> 标签内？是否为\"[标题]内容\"格式？选项数量是否等于 {{count}}？每条字数是否在 {{min_chars}}-{{max_chars}} 个中文字符之间？内容中是否误用了[]符号？\n\n完成以上自检后，直接进入 <options> 输出，不额外解释自检过程。","marker":false,"system":false,"enabled":true,"order":19,"option_only":true},{"id":"assistant_thinking","name":"思维链开头","role":"assistant","content":"好的，开始处理任务，按自检顺序逐条梳理检查点。\n\n<thinking>\n","marker":false,"system":false,"enabled":true,"order":20,"option_only":true},{"id":"enrich_core_rules","name":"润色规则","role":"system","content":"【润色规则】\n\n【忠实度】\n1. 必须保留原文的完整语义和语气基调，不得改变原文的核心意思。\n2. {{enrich_person_style}}\n3. 不得改变原文的情感基调与态度强度（如将愤怒改为平静、将暧昧改为冷淡）。\n4. 原文中引号标注的直接对白（如『……』或\"……\"）必须保留为直接引语形式，可对内容本身进行润色但严禁改写为间接叙述，禁止使用\"他说……\"\"他告诉……\"\"他坦言……\"\"他诉说道……\"等概括性表述替代原文对白。\n\n【表达质量】\n5. 润色是\"换一种说法\"，不是\"换一个意思\"——每个版本都应是对原文同一语义的重新表达。\n6. 通过变换句式结构、措辞选择、细节密度来制造版本差异。\n\n【格式规范】\n7. 每个版本字数控制在 {{min_chars}}-{{max_chars}} 个中文字符之间。\n8. 输出格式见【润色输出规格】模块，此处不再重复。","marker":false,"system":false,"enabled":true,"order":21,"enrich_only":true},{"id":"enrich_output_spec","name":"润色输出规格","role":"system","content":"【润色输出规格】\n\n数量：恰好 {{count}} 个版本，不多不少。\n\n字数：每个版本字数控制在 {{min_chars}}-{{max_chars}} 个中文字符之间。\n\n格式：每行一个版本，格式为 \"[标题]内容\"\n- 标题：简洁概括该版本的风格或特点，用[]包裹\n- 正文：润色后的完整句子，不含编号或额外标注，严禁使用[]符号\n\n输出结构：\n1. 先输出完整的 <thinking> 分析块\n2. 再输出 <options> 选项块，每个版本独占一行\n3. 两者之外不得有任何文字","marker":false,"system":false,"enabled":true,"order":22,"enrich_only":true},{"id":"enrich_thinking","name":"润色自检","role":"system","content":"【润色前自检 - 全部内容须包裹在 <thinking> 标签内】\n请按顺序逐条检查并简要记录结论：\n1. 原文理解：用户输入的核心语义是什么？语气基调（轻松/严肃/暧昧/愤怒等）是什么？\n2. 多样性检查：{{count}} 个版本之间在描写角度、措辞风格上是否有明显区分？是否存在仅做同义词替换的重复版本？\n3. 忠实度检查：每个润色版本是否保留了原文的完整语义？是否有任何版本改变了原文的核心意思？原文中的直接对白是否保持直接引语形式，未被改写为间接叙述？\n4. 人称检查：每个版本是否以 {{enrich_person}} 为主语视角？\n5. 格式与字数检查：是否为恰好 {{count}} 个版本？每行格式是否为 \"[标题]内容\"？内容中是否误用了[]符号？每个版本字数是否在 {{min_chars}}-{{max_chars}} 个中文字符之间？\n\n完成以上自检后，直接输出润色结果，不额外解释自检过程。","marker":false,"system":false,"enabled":true,"order":23,"enrich_only":true},{"id":"enrich_assistant","name":"润色应答","role":"assistant","content":"好的，开始处理润色任务，先逐条理解原文并自检人称、字数、忠实度。\n\n<thinking>\n","marker":false,"system":false,"enabled":true,"order":24,"enrich_only":true}];
